function editProperty(id){if(!canEdit())throw Error('Acesso restrito.');location.href='/admin/imoveis/'+(id?encodeURIComponent(id)+'/editar':'novo');}
function showPropertyPage(label,body){$('#app').innerHTML=adminShell('imoveis',`<div class="property-editor-page"><div class="property-editor-head"><h1>${tr(label,lang)}</h1><button type="button" class="btn" data-action="property-back">${tr('Voltar à lista',lang)}</button><button class="btn primary" type="submit" form="property-form">${tr('Salvar imóvel',lang)}</button></div>${body}</div>`);organizePropertyForm($('#property-form'),text=>tr(text,lang));$('#property-form').insertAdjacentHTML('afterbegin','<section id="property-quality" class="note" aria-live="polite"></section>');$('#field-location').required=false;const quality=()=>{const f=Object.fromEntries(new FormData($('#property-form'))),photos=(()=>{try{return photoEditor?.value()||draft;}catch{return draft;}})(),p={...draft,...f,...photos,priceOnRequest:!!f.priceOnRequest};if(draftLang!=='pt'){p.title=draft.title;p.description=draft.description;p.translations={...draft.translations,[draftLang]:{...draft.translations?.[draftLang],title:f.title,description:f.description}};}const issues=propertyIssues(p),labels={title:'Título',area:'Área',price:'Preço',location:'Localização',description:'Descrição',image:'Fotos',main:'Fotos'};$('#property-form').noValidate=f.status==='Rascunho';$('#property-quality').innerHTML=['required','recommended'].map(kind=>'<h3>'+tr(kind==='required'?'Obrigatório para publicar':'Recomendações de qualidade',lang)+'</h3><ul>'+issues[kind].map(key=>'<li><a href="#'+(key.startsWith('translation-')?'draft-lang':key==='image'||key==='main'?'property-photos':key==='description'?'draft-description':'field-'+key)+'">'+esc(tr(labels[key]||'Traduções',lang))+(key.startsWith('translation-')?' '+key.slice(-2).toUpperCase():'')+'</a></li>').join('')+'</ul>').join('');};$('#property-form').addEventListener('input',quality);$('#property-form').addEventListener('change',()=>setTimeout(quality,0));$('#property-form').addEventListener('photo-editor-update',()=>setTimeout(quality,0));queueMicrotask(quality);translateDOM($('#app'),lang);propertyGuard?.dispose();propertyGuard=installDirtyGuard($('#property-form'),{message:()=>tr('Descartar alterações não salvas?',lang)});}
let properties=[],settings={},session={},leads=[],visits=[],staff=[],users=[],draft=null,draftLang='pt',galleryIndex=0,detailTab='Visão geral',activeFilter='Todos',purpose='Comprar',sort='new';
let savedFavorites=[];try{savedFavorites=JSON.parse(localStorage.getItem('confianza-favorites')||'[]');if(!Array.isArray(savedFavorites))savedFavorites=[];}catch{}let favorites=new Set(savedFavorites);let filters={q:'',type:'',max:'',minArea:'',region:''};
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.9-8.6a5.5 5.5 0 0 0-.1-7.8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',leaf:'M20 3c-10-1-17 6-14 13 7 3 14-4 14-13ZM4 21 16 9',building:'M5 21V3h14v18M9 7h1m4 0h1M9 11h1m4 0h1M9 15h1m4 0h1M10 21v-3h4v3',key:'M15 10a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM15 10h7m-2 0v4',bed:'M3 18V7m0 7h18v4M6 14V9h6v5m0-3h9v3M3 18v3m18-3v3',bath:'M3 12h18v3a6 6 0 0 1-6 6H9a6 6 0 0 1-6-6v-3ZM5 12V4a2 2 0 0 1 4 0M7 5h4',area:'M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6M8 8l8 8m-8 0 8-8',check:'m5 12 4 4L19 6',menu:'M3 6h18M3 12h18M3 18h18',close:'m6 6 12 12M6 18 18 6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M12 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M22 21v-3a4 4 0 0 0-3-4M16 2a4 4 0 0 1 0 8',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 2h6l1 3 3 1 3 3v6l-3 3-3 1-1 3H9l-1-3-3-1-3-3V9l3-3 3-1 1-3',mail:'M3 5h18v14H3V5Zm0 0 9 8 9-8',phone:'M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4c-10 4-20-6-16-16',calendar:'M4 5h16v16H4V5Zm0 5h16M8 2v6m8-6v6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',plus:'M12 4v16M4 12h16',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15v5Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',logout:'M9 4H3v16h6m5-13 5 5-5 5M8 12h13',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6l-9-4Zm-4 10 3 3 5-6',cloud:'M6 15a5 5 0 1 1 2-9 6 6 0 0 1 11 4 3 3 0 0 1-1 5M8 19v3m4-3v3m4-3v3',compare:'M6 3v18M18 3v18M3 7h6m6 10h6M3 3h6m6 18h6',share:'M18 5 6 12l12 7M21 5a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM9 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM21 19a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
const logo=()=>`<a class="logo" href="/"><svg class="logo-mark" viewBox="0 0 40 44" aria-hidden="true"><path d="M4 32V19L20 6l16 13v13M10 29V21l10-8 10 8v8M15 38V24h10v14M2 39h36"/></svg><div><div class="logo-name" data-no-translate>${esc(settings.name||'Confianza').toUpperCase()}</div><div class="logo-sub">${esc(settings.tagline||'Imóveis & Terras')}</div></div></a>`;
const languageSelect=()=>`<select data-language aria-label="Idioma" style="background:transparent;border:0;font-size:11px;color:inherit;max-width:83px">${Object.entries(languageNames).map(([k,v])=>`<option value="${k}" ${k===lang?'selected':''}>${v}</option>`).join('')}</select>`;
const money=p=>p.priceOnRequest?tr('Preço sob consulta',lang):new Intl.NumberFormat(locales[lang],{style:'currency',currency:p.currency||'BRL',maximumFractionDigits:0}).format(p.price||0);
const number=n=>new Intl.NumberFormat(locales[lang],{maximumFractionDigits:1}).format(n||0);
const img=x=>x?.startsWith('https://')||x?.startsWith('/api/media/')?esc(x):'/portal/assets/'+esc(x||'house.jpg');
const title=p=>p.translations?.[lang]?.title||p.title;
const translatedFeatures=p=>p.translations?.[lang]?.features?.length?p.translations[lang].features:p.features;
const description=p=>p.translations?.[lang]?.description||p.description;
const canEdit=()=>['admin','editor'].includes(session.role);
const statuses=['Novo','Em atendimento','Visita agendada','Concluído'];
function toast(s){$('#toast').textContent=tr(s,lang);$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
async function api(path,method='GET',data){const r=await fetch('/api/'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const x=await r.json();if(!r.ok)throw Error(x.error||tr('Não foi possível carregar os dados. Tente novamente.',lang));return x;}
function header(){return `<header class="header">${logo()}<nav id="nav"><a href="/buscar?purpose=Comprar">Comprar</a><a href="/buscar?purpose=Alugar">Alugar</a><a href="/buscar?type=Fazenda">Fazendas</a><a href="/buscar?purpose=Lançamentos">Lançamentos</a><a href="/comparar">${tr('INTELIGÊNCIA RURAL',lang).toLocaleLowerCase().replace(/^./,x=>x.toUpperCase())}</a><a href="/sobre">Sobre nós</a></nav><div class="header-actions">${languageSelect()}<a class="favorite-link flex" href="/favoritos">${icon('heart')}<span>Favoritos</span></a><a class="admin-link" href="/admin">Entrar</a><button class="btn primary" data-action="contact" data-kind="Anúncio de imóvel">Anunciar imóvel</button><button class="menu-btn" data-action="menu" aria-label="Navegação">${icon('menu')}</button></div></header>`;}
function footer(){return `<footer><div class="container"><div class="footer-grid"><div>${logo()}<p>Uma ponte entre seus planos e o lugar ideal. Imóveis urbanos e rurais com uma nova perspectiva.</p></div><div><h4>Navegação</h4><a href="/buscar?purpose=Comprar">Comprar</a><a href="/buscar?purpose=Alugar">Alugar</a><a href="/buscar?type=Fazenda">Fazendas</a><a href="/buscar?purpose=Lançamentos">Lançamentos</a></div><div><h4>Institucional</h4><a href="/sobre">Sobre nós</a><a href="/privacidade">Privacidade</a><a href="/admin">Administração</a><a href="/comparar">Comparar propriedades</a></div><div><h4>Contato</h4>${settings.phone?`<a href="tel:${esc(settings.phone.replace(/[^+\d]/g,''))}">${esc(settings.phone)}</a>`:''}${settings.email?`<a href="mailto:${esc(settings.email)}">${esc(settings.email)}</a>`:''}${settings.address?`<p data-no-translate>${esc(settings.address)}</p>`:''}<button class="btn" data-action="contact">${icon('mail')}Fale conosco</button></div></div>${settings.demo?'<p class="demo-note">Catálogo demonstrativo. Imóveis, fotos e valores ilustrativos; não representam ofertas reais.</p>':''}<div class="copyright"><span>© ${new Date().getFullYear()} <span data-no-translate>${esc(settings.name||'Confianza')}</span>. <span>Todos os direitos reservados.</span></span><span>PT · ES · IT · EN · DE</span></div></div></footer>`;}
function searchBox(){return `<div class="search-box"><div class="search-tabs">${[['Comprar','home'],['Alugar','key'],['Fazendas','leaf'],['Lançamentos','building']].map(([t,i])=>`<button data-action="purpose" data-value="${t}" class="${purpose===t?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</div><form id="search-form"><div class="search-fields"><div class="search-field"><label for="q">Localização</label><input id="q" name="q" placeholder="Cidade, bairro ou região" value="${esc(filters.q)}"></div><div class="search-field"><label for="type">Tipo de imóvel</label><select id="type" name="type"><option value="">Todos os tipos</option>${['Casa','Apartamento','Fazenda','Terreno'].map(t=>`<option value="${t}" ${filters.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="search-field"><label for="max">Faixa de preço</label><select id="max" name="max"><option value="">Qualquer valor</option><option value="2000000" ${filters.max==='2000000'?'selected':''}>Até R$ 2 milhões</option><option value="5000000" ${filters.max==='5000000'?'selected':''}>Até R$ 5 milhões</option></select></div><button class="btn primary" type="submit">${icon('search')}Buscar imóveis</button></div><div class="search-foot"><button type="button" data-action="advanced">Busca avançada ${icon('plus')}</button><span>Encontre o lugar que combina com o seu momento.</span></div></form></div>`;}
function card(p){return `<article class="card"><a class="card-image" href="/imovel/${encodeURIComponent(p.id)}"><img src="${img(p.image)}" alt="${esc(title(p))}" loading="lazy" width="600" height="440"><span class="badge ${p.type==='Fazenda'?'rural':''}">${tr(p.tag||p.type,lang)}</span></a><button class="favorite ${favorites.has(p.id)?'saved':''}" data-action="favorite" data-id="${p.id}" aria-label="Favoritos" aria-pressed="${favorites.has(p.id)}">${icon('heart')}</button><div class="card-body"><p class="card-category">${tr(p.type,lang)} · ${tr(p.purpose,lang)}</p><a href="/imovel/${p.id}"><h3 data-no-translate>${esc(title(p))}</h3></a><p class="location" data-no-translate>${icon('pin')}${esc(p.location)}</p><div class="features">${p.type==='Fazenda'?`${icon('area')}<span>${number(p.area)} ha</span>${icon('leaf')}<span>${p.productive?number(p.productive)+' ha':tr('Consultar equipe',lang)}</span>`:`${icon('bed')}<span>${number(p.beds)}</span>${icon('bath')}<span>${number(p.baths)}</span>${icon('area')}<span>${number(p.area)} m²</span>`}</div><div class="price"><span>${money(p)}${p.purpose==='Alugar'?` <small>${tr('por mês',lang)}</small>`:''}</span><a href="/imovel/${p.id}" aria-label="${esc(title(p))}">${icon('arrow')}</a></div></div>${p.type==='Fazenda'?`<button class="card-bottom" style="width:100%;text-align:left" data-action="compare" data-id="${p.id}">${icon('compare')} Comparar fazenda</button>`:''}</article>`;}
function home(){const published=properties.filter(p=>p.status==='Publicado');let selected=published.filter(p=>activeFilter==='Todos'?p.featured:p.type===({Casas:'Casa',Apartamentos:'Apartamento',Fazendas:'Fazenda',Terrenos:'Terreno'}[activeFilter]));return `${header()}<main><section class="hero"><img class="hero-house" src="/portal/assets/hero.jpg" alt="Casa contemporânea com piscina" fetchpriority="high" width="1800" height="1194"><img class="hero-farm" src="/portal/assets/farm.jpg" alt="Paisagem rural" width="1000" height="667"><div class="container hero-content"><div class="eyebrow">NOVOS ENDEREÇOS. NOVOS HORIZONTES.</div><h1><span>Seu próximo capítulo</span><br><em>começa aqui.</em></h1><p>Um lugar para viver. Uma terra para produzir. Uma oportunidade para transformar o amanhã.</p></div><div class="hero-bottom"><span>URBANO & RURAL</span><span>BRASIL · PARAGUAY</span></div></section><div class="container"><div class="search-wrap">${searchBox()}</div><div class="stats">${[['home','Imóveis selecionados','Urbano e rural em um só lugar'],['users','Atendimento próximo','Do primeiro contato à sua conquista'],['pin','Diferentes horizontes','Brasil e Paraguai no catálogo'],['globe','Equipe multilíngue','Cinco idiomas. Mais conexões.']].map(([i,t,s])=>`<div class="stat">${icon(i)}<div><strong>${t}</strong><span>${s}</span></div></div>`).join('')}</div><section class="section"><div class="section-title"><div><div class="eyebrow">NOSSA SELEÇÃO</div><h2>Lugares que merecem seu olhar.</h2><p>Explore possibilidades para morar, investir ou produzir.</p></div><a class="text-link" href="/buscar">Ver todos os imóveis ${icon('arrow')}</a></div><div class="filter-row">${['Todos','Casas','Apartamentos','Fazendas','Terrenos'].map(t=>`<button class="pill ${activeFilter===t?'active':''}" data-action="filter" data-value="${t}">${t}</button>`).join('')}</div><div class="grid">${selected.length?selected.slice(0,4).map(card).join(''):'<div class="empty">Nenhum imóvel encontrado. Tente ajustar os filtros.</div>'}</div></section><section class="rural-block"><div class="rural-content"><div class="eyebrow">INTELIGÊNCIA RURAL</div><h2>Terra fértil para grandes planos.</h2><p>Conheça propriedades rurais com uma visão mais completa: área produtiva, infraestrutura e características da terra, lado a lado.</p><div class="flex" style="flex-wrap:wrap"><a href="/buscar?type=Fazenda" class="btn gold">Explorar fazendas ${icon('arrow')}</a><a href="/comparar" class="btn clear">Comparar propriedades</a></div></div><div class="rural-image"><img src="/portal/assets/fields.jpg" alt="Campos e áreas rurais" loading="lazy" width="1000" height="667"><div class="rural-note"><strong>Novas possibilidades</strong><span>para quem pensa além.</span></div></div></section><section class="section"><div class="section-title"><div><h2>O potencial está nos detalhes.</h2></div></div><div class="insight-grid">${[['area','Área e uso da terra','Entenda a distribuição da propriedade e seus espaços produtivos.'],['leaf','Características naturais','Solo, clima e recursos informados para orientar sua avaliação.'],['compare','Visão comparativa','Compare propriedades e encontre a oportunidade que faz sentido.']].map(([i,t,p])=>`<div class="insight-card">${icon(i)}<div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div></section><section style="padding-bottom:50px"><div class="section-title"><div><div class="eyebrow">ENCONTRE SEU LUGAR</div><h2>Diferentes regiões. A mesma confiança.</h2></div></div><div class="regions">${['Sul','Centro-Oeste','Sudeste','Paraguai'].map(r=>`<a class="region" href="/buscar?region=${encodeURIComponent(r)}"><div><h3>${r}</h3><p>Explorar região</p></div>${icon('pin')}</a>`).join('')}</div></section></div><section class="why"><div class="container why-grid"><h2>Confiança em cada etapa.</h2>${[['shield','Escolhas bem informadas','Informações claras para avaliar cada oportunidade.'],['users','Conexões humanas','Uma equipe que escuta e acompanha a sua jornada.'],['globe','Novos horizontes','Possibilidades para morar, investir e produzir.']].map(([i,t,p])=>`<div class="why-item">${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><div class="container"><div class="contact-banner"><div><h2>Vamos encontrar seu próximo endereço?</h2><p>Conte seus planos. Nossa equipe ajuda a dar o próximo passo.</p></div><button class="btn primary" data-action="contact">Falar com a equipe ${icon('arrow')}</button></div></div></main>${footer()}`;}
function route(){return location.hash.startsWith('#/')?location.hash.slice(1):location.pathname.replace(/^\/portal\/index\.html$/, '/')+location.search;}
function listPage(saved=false){const url=new URL('https://local'+route());let rows=properties.filter(p=>p.status==='Publicado');const q=url.searchParams.get('q')||'',type=url.searchParams.get('type')||'',pur=url.searchParams.get('purpose')||'',reg=url.searchParams.get('region')||'',max=Number(url.searchParams.get('max')),minArea=Number(url.searchParams.get('minArea'));
 if(saved)rows=rows.filter(p=>favorites.has(p.id));else rows=rows.filter(p=>(!q||(title(p)+' '+p.location).toLowerCase().includes(q.toLowerCase()))&&(!type||p.type===type)&&(!pur||p.purpose===pur)&&(!reg||p.region===reg)&&(!max||(!p.priceOnRequest&&p.currency==='BRL'&&p.price<=max))&&(!minArea||p.area>=minArea));
 if(sort==='asc'||sort==='desc')rows.sort((a,b)=>Number(!!a.priceOnRequest)-Number(!!b.priceOnRequest)||a.currency.localeCompare(b.currency)||(sort==='asc'?a.price-b.price:b.price-a.price));
 return `${header()}<main class="container page-space"><div class="breadcrumb"><a href="/">Início</a>${icon('chevron')}<span>${saved?'Favoritos':'Resultados da busca'}</span></div><div class="list-head"><div class="eyebrow">${saved?'Favoritos':'Imóveis'}</div><h1>${saved?'Favoritos':'Seu próximo lugar está aqui.'}</h1><p class="muted small">${saved?'Favoritos salvos neste dispositivo.':'Explore possibilidades para morar, investir ou produzir.'}</p></div>${saved?'':searchBox()}<div class="result-toolbar"><span>${number(rows.length)} ${tr('Imóveis',lang).toLowerCase()}</span><select id="sort" aria-label="Situação"><option value="new" ${sort==='new'?'selected':''}>Mais recentes</option><option value="asc" ${sort==='asc'?'selected':''}>Menor preço</option><option value="desc" ${sort==='desc'?'selected':''}>Maior preço</option></select></div><div class="grid">${rows.length?rows.map(card).join(''):`<div class="empty">${saved?'Você ainda não salvou favoritos.':'Nenhum imóvel encontrado. Tente ajustar os filtros.'}</div>`}</div></main>${footer()}`;}
function detail(){const id=decodeURIComponent(route().split('/')[2]||'');const p=properties.find(x=>x.id===id&&x.status==='Publicado');if(!p)return `${header()}<div class="container section empty">Nenhum imóvel encontrado. Tente ajustar os filtros.</div>${footer()}`;const gallery=photoRefs(p).length?photoRefs(p):['house.jpg'];galleryIndex%=gallery.length;const tabs=['Visão geral','Características','Solo e clima','Documentação'];let info='';
 if(detailTab==='Visão geral')info=`<div class="detail-info"><div class="info-box"><h3>Localização</h3><div class="map-placeholder"><svg viewBox="0 0 250 130"><path d="M0 10 120 100 200 10M10 130 190 20 250 100M0 80 250 50" fill="none" stroke="#93a28b" stroke-width="12"/></svg><span data-no-translate>${icon('pin')}${esc(p.location)}</span></div><a class="text-link small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.latitude&&p.longitude?p.latitude+','+p.longitude:p.location)}" target="_blank" rel="noopener">Abrir mapa ${icon('arrow')}</a></div><div class="info-box"><h3>${p.type==='Fazenda'?'Uso da terra':'Área total'}</h3>${p.type==='Fazenda'&&p.productive?`<div class="donut" style="background:conic-gradient(var(--green) 0 ${Math.min(100,p.productive/p.area*100)}%,var(--gold) ${Math.min(100,p.productive/p.area*100)}% 100%)"><div>${number(p.area)} ha<small>Área total</small></div></div><p style="text-align:center;margin-top:13px">${number(p.productive)} ha · ${tr('Área produtiva',lang)}</p>`:`<div style="padding:25px 0;text-align:center">${icon('area')}<h2>${number(p.area)} ${p.unit}</h2></div>`}</div><div class="info-box"><h3>Características</h3><ul>${(translatedFeatures(p)||[]).map(f=>`<li>${icon('check')}<span data-no-translate>${esc(f)}</span></li>`).join('')}</ul></div></div>`;
 if(detailTab==='Características')info=`<div class="info-box"><h3>Infraestrutura</h3><ul>${translatedFeatures(p).map(f=>`<li>${icon('check')}<span data-no-translate>${esc(f)}</span></li>`).join('')}</ul><p>Dados informados pelo anunciante. Confirme em visita e documentação.</p></div>`;
 if(detailTab==='Solo e clima')info=`<div class="detail-info"><div class="info-box"><h3>Solo predominante</h3>${icon('leaf')}<p data-no-translate>${esc(p.soil||tr('Não informado',lang))}</p></div><div class="info-box"><h3>Chuva média anual</h3>${icon('cloud')}<p>${p.rain?number(p.rain)+' mm '+tr('/ano',lang):tr('Não informado',lang)}</p></div><div class="info-box"><h3>Reserva natural</h3>${icon('shield')}<p>${p.reserve?number(p.reserve)+' ha':tr('Não informado',lang)}</p></div></div>`;
 if(detailTab==='Documentação')info=`<div class="info-box"><h3>Documentação</h3><p>Documentação e dados técnicos disponíveis sob consulta com a equipe.</p><button class="btn primary" style="margin-top:18px" data-action="contact" data-id="${p.id}">Consultar equipe</button></div>`;
 return `${header()}<main class="container page-space"><div class="breadcrumb"><a href="/">Início</a>${icon('chevron')}<a href="/buscar">Imóveis</a>${icon('chevron')}<span data-no-translate>${esc(title(p))}</span><button style="margin-left:auto" data-action="share">${icon('share')} Compartilhar</button></div><div class="detail-layout"><div><div class="gallery-main"><img src="${img(gallery[galleryIndex])}" alt="${esc(title(p))}" width="1200" height="800"><span class="badge rural">${tr(p.tag||p.type,lang)}</span><div class="gallery-controls"><button data-action="gallery" data-value="-1" style="transform:rotate(180deg)" aria-label="${tr('Foto anterior',lang)}">${icon('chevron','')}<span class="hidden">←</span></button><button data-action="gallery" data-value="1" aria-label="${tr('Próxima foto',lang)}">${icon('chevron')}</button></div><span class="gallery-count">${galleryIndex+1} / ${gallery.length}</span></div><div class="thumbnails">${gallery.map((g,i)=>`<button data-action="thumbnail" data-value="${i}" class="${galleryIndex===i?'active':''}"><img src="${img(g)}" alt="${esc(title(p))} ${i+1}" loading="lazy"></button>`).join('')}</div><div class="detail-title flex between"><h1 data-no-translate>${esc(title(p))}</h1><button data-action="favorite" data-id="${p.id}" aria-label="Favoritos">${icon('heart')}</button></div><div class="location" data-no-translate>${icon('pin')}${esc(p.location)}</div><div class="detail-prices"><div><label>Valor total</label><strong>${money(p)}</strong></div><div><label>Área total</label><strong>${number(p.area)} ${p.unit}</strong></div><div><label>${p.type==='Fazenda'?'Preço por hectare':'Quartos'}</label><strong>${p.type==='Fazenda'?money({...p,price:p.price/p.area}):number(p.beds)}</strong></div></div><div class="flex detail-cta"><button class="btn primary" data-action="contact" data-id="${p.id}">${icon('mail')}Falar com corretor</button><button class="btn" data-action="contact" data-id="${p.id}" data-kind="Visita">${icon('calendar')}Agendar visita</button><button class="btn" data-action="presentation" data-id="${p.id}">${icon('download')}Baixar apresentação</button></div><div class="property-tabs">${tabs.map(t=>`<button class="${detailTab===t?'active':''}" data-action="detail-tab" data-value="${t}">${t}</button>`).join('')}</div><div>${info}</div><div class="info-box" style="margin-top:20px"><h3>Sobre a propriedade</h3><p data-no-translate>${esc(description(p))}</p>${lang!=='pt'&&!p.translations?.[lang]?.description?'<p class="note">Tradução não cadastrada: exibindo o conteúdo original.</p>':''}</div></div><aside class="specialist"><h3>Falar com um especialista</h3><div class="flex"><div class="avatar">C</div><div><strong>Equipe Confianza</strong><div class="muted small" style="margin-top:5px">Atendimento em cinco idiomas</div></div></div><p>Conte com nossa equipe para conhecer os detalhes e planejar uma visita.</p><button class="btn primary" data-action="contact" data-id="${p.id}">Falar com corretor ${icon('arrow')}</button>${settings.whatsapp?`<a class="btn" href="https://wa.me/${esc(settings.whatsapp)}?text=${encodeURIComponent(tr('Contato',lang)+': '+title(p)+' '+location.origin+'/imovel/'+encodeURIComponent(p.id))}" target="_blank" rel="noopener">Falar no WhatsApp</a>`:''}<p style="font-size:9px">PT · ES · IT · EN · DE</p>${settings.demo?'<p class="note">Informações ilustrativas</p>':''}</aside></div><section class="section"><div class="section-title"><h2>Imóveis semelhantes</h2><a class="text-link" href="/buscar">Ver todos os imóveis ${icon('arrow')}</a></div><div class="grid">${properties.filter(x=>x.id!==p.id&&x.status==='Publicado'&&x.type===p.type).slice(0,4).map(card).join('')}</div></section></main>${footer()}`;}
function comparison(){const farms=properties.filter(p=>p.type==='Fazenda'&&p.status==='Publicado');const u=new URL('https://local'+route()),a=farms.find(p=>p.id===u.searchParams.get('a'))||farms[0],b=farms.find(p=>p.id===u.searchParams.get('b'))||farms.find(p=>p.id!==a?.id);const rows=[['Localização',p=>esc(p.location)],['Valor total',p=>money(p)],['Área total',p=>number(p.area)+' ha'],['Área produtiva',p=>p.productive?number(p.productive)+' ha':tr('Não informado',lang)],['Preço por hectare',p=>money({...p,price:p.price/p.area})],['Solo',p=>esc(p.soil||tr('Não informado',lang))],['Chuva média anual',p=>p.rain?number(p.rain)+' mm':tr('Não informado',lang)],['Reserva natural',p=>p.reserve?number(p.reserve)+' ha':tr('Não informado',lang)]];
 return `${header()}<main class="container page-space"><div class="breadcrumb"><a href="/">Início</a>${icon('chevron')}<span>Comparador de fazendas</span></div><div class="list-head"><div class="eyebrow">INTELIGÊNCIA RURAL</div><h1>Comparador de fazendas</h1><p class="muted">Compare os dados informados, lado a lado.</p></div>${farms.length<2?'<div class="empty">Nenhum imóvel encontrado. Tente ajustar os filtros.</div>':`<div class="compare-select">${[['a','Primeira propriedade',a],['b','Segunda propriedade',b]].map(([key,label,p])=>`<div style="flex:1"><label for="compare-${key}">${label}</label><select id="compare-${key}" data-compare="${key}">${farms.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(title(x))}</option>`).join('')}</select></div>`).join('')}</div><div class="table-wrap"><table class="compare-table"><thead><tr><th>Propriedade</th>${[a,b].map(p=>`<th data-no-translate><a href="/imovel/${p.id}">${esc(title(p))}<img src="${img(p.image)}" alt="${esc(title(p))}" style="margin-top:15px"></a></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td><td data-no-translate>${fn(a)}</td><td data-no-translate>${fn(b)}</td></tr>`).join('')}</tbody></table></div><p class="note">Reservas e informações técnicas devem ser validadas por profissionais habilitados.</p>`}</main>${footer()}`;}
function basicPage(type){return `${header()}<main class="container section page-space" style="max-width:900px"><div class="eyebrow">Confianza</div><h1 class="serif" style="font-size:42px;margin-bottom:25px">${type==='sobre'?'Sobre a Confianza':'Privacidade'}</h1><p style="line-height:2;font-size:15px;color:var(--muted)">${type==='sobre'?'Um novo olhar sobre imóveis urbanos e rurais. Conectamos pessoas a oportunidades, com informações organizadas e atendimento em português, espanhol, italiano, inglês e alemão.':'Seus dados de contato são usados para atender sua solicitação. Para exercer seus direitos de acesso, correção ou exclusão, fale com a equipe pelos canais cadastrados. Favoritos e idioma ficam salvos apenas neste dispositivo.'}</p><button class="btn primary" style="margin-top:30px" data-action="contact">Falar com a equipe</button></main>${footer()}`;}
const qrUI=createWhatsAppQRUI({state:()=>({session,leads,staff,lang}),api,esc,tr});
const team=createTeamUI({state:()=>({session,properties,leads,staff,lang}),api,esc,img,tr,showModal,refresh,render,cleanEditor:()=>propertyGuard?.clean()});
function adminShell(page,body){return `<a class="skip-link" href="#main-content">${tr('Ir para o conteúdo',lang)}</a><div class="admin-shell"><aside class="admin-sidebar">${logo()}<div class="eyebrow">ÁREA ADMINISTRATIVA</div>${[['dashboard','chart','Painel'],['imoveis','building','Imóveis'],['contatos','mail','Contato'],['pendencias','calendar','Pendências'],['relatorios','chart','Relatórios'],['notificacoes','mail','Notificações'],['conversas','mail','Conversas por WhatsApp'],['organizar','users','Organizar contatos'],['desempenho','chart','Desempenho'],...(session.role==='admin'?[['backups','shield','Verificação de backups']]:[]),['visitas','calendar','Visitas agendadas'],...(session.role==='admin'?[['equipe','users','Equipe'],['configuracoes','settings','Configurações']]:[])].map(([key,i,t])=>`<button class="${page===key?'active':''}" data-action="navigate" aria-label="${tr(t,lang)}" data-value="/admin/${key}">${icon(i)}<span>${t}</span></button>`).join('')}<div class="bottom"><button data-action="navigate" data-value="/">${icon('globe')}<span>Ver site</span></button>${session.mode==='node'?`<button data-action="logout">${icon('logout')}<span>Sair</span></button>`:''}</div></aside><main class="admin-content" id="main-content" tabindex="-1">${team.toolbar()}<div class="admin-header"><div class="flex"><span class="header-admin-tag">ÁREA ADMINISTRATIVA</span><span> / </span><strong>${tr({dashboard:'Painel',imoveis:'Imóveis',contatos:'Contato',visitas:'Visitas agendadas',pendencias:'Pendências',relatorios:'Relatórios',notificacoes:'Notificações',conversas:'Conversas por WhatsApp',organizar:'Organizar contatos',desempenho:'Desempenho',backups:'Verificação de backups',equipe:'Equipe',configuracoes:'Configurações'}[page]||'Painel',lang)}</strong></div><div class="flex">${languageSelect()}<div class="avatar">${esc((session.name||'A').slice(0,1).toUpperCase())}</div><span data-no-translate>${esc(session.name||'Confianza')}</span></div></div>${body}</main></div>`;}
function dashboard(){const counts=statuses.map(s=>leads.filter(l=>l.status===s).length),days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return{label:d.toLocaleDateString(locales[lang],{weekday:'short'}),count:leads.filter(l=>l.date.slice(0,10)===d.toISOString().slice(0,10)).length};}),max=Math.max(1,...days.map(d=>d.count));return `<h1>Bem-vindo à sua visão geral.</h1><p class="muted small">Acompanhe seus imóveis e novas oportunidades.</p><div class="admin-kpis">${[['Imóveis publicados',properties.filter(p=>p.status==='Publicado').length,'Ativos no site','home'],['Contatos recebidos',leads.length,'Novas conexões','mail'],['Visitas agendadas',counts[2],'Em acompanhamento','calendar'],['Total no catálogo',properties.length,'Publicados e rascunhos','building']].map(([t,n,s,i])=>`<div class="kpi"><div class="kpi-top"><span>${t}</span>${icon(i)}</div><strong>${number(n)}</strong><small>${s}</small></div>`).join('')}</div><div class="admin-panels"><div class="panel"><div class="panel-head"><h3>Contatos nos últimos 7 dias</h3>${icon('chart')}</div><div class="bar-chart">${days.map(d=>`<div class="bar" style="height:${Math.max(2,d.count/max*85)}%"><em>${number(d.count)}</em><span>${d.label}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>Funil de atendimento</h3>${icon('users')}</div>${statuses.map((s,i)=>`<div class="pipeline-row"><span><i></i>${s}</span><strong>${number(counts[i])}</strong></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h3>Últimos contatos</h3><a class="text-link" href="/admin/contatos">Ver contatos ${icon('arrow')}</a></div>${leads.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Propriedade</th><th>Situação</th><th>Data</th></tr></thead><tbody>${leads.slice(0,5).map(l=>`<tr><td data-no-translate>${esc(l.name)}</td><td data-no-translate>${esc(l.property)}</td><td><span class="status">${l.status}</span></td><td>${new Date(l.date).toLocaleDateString(locales[lang])}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum contato recebido ainda.</div>'}</div>`;}
function propertyAdmin(){return `<div class="flex between"><div><h1>Imóveis</h1><p class="muted small">Gerencie seu catálogo.</p></div>${canEdit()?`<button class="btn primary" data-action="edit-property">${icon('plus')}Novo imóvel</button>`:''}</div><div class="admin-toolbar"><input id="admin-search" class="admin-search" placeholder="Buscar no catálogo">${session.role==='admin'?'<button class="btn" data-action="audit-download">Baixar auditoria</button>':''}<button class="btn" data-action="export" data-value="properties">${icon('download')}Exportar CSV</button></div><div class="panel"><div class="table-wrap"><table id="property-table"><thead><tr><th>Propriedade</th><th>Finalidade</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${properties.map(p=>`<tr data-row="${esc((title(p)+' '+p.location).toLowerCase())}"><td><div class="row-property"><img src="${img(p.image)}" alt=""><div><strong data-no-translate>${esc(title(p))}</strong><span data-no-translate>${esc(p.location)}</span><a class="quality-link" href="/admin/imoveis/${encodeURIComponent(p.id)}/editar#property-quality">${propertyIssues(p).required.length+propertyIssues(p).recommended.length} ${tr('Pendências do cadastro',lang)}</a></div></div></td><td>${p.purpose}</td><td>${money(p)}</td><td><span class="status ${p.status!=='Publicado'?'gray':''}">${p.status}</span></td><td><div class="actions">${canEdit()?`<button data-action="edit-property" data-id="${p.id}" aria-label="Editar imóvel">${icon('edit')}</button><button data-action="delete-property" data-id="${p.id}" aria-label="Excluir">${icon('trash')}</button>`:''}${session.commissionPermissions?.view?`<button data-action="commission-view" data-id="${p.id}" aria-label="Comissões internas">${icon('users')}</button>`:''}<button data-action="team-history" data-id="${p.id}" aria-label="${tr('Histórico de versões',lang)}">${icon('calendar')}</button>${p.status==='Publicado'?`<button data-action="presentation" data-id="${p.id}" aria-label="Preparar apresentação">${icon('download')}</button>`:''}<a href="/imovel/${p.id}" aria-label="Ver site">${icon('arrow')}</a></div></td></tr>`).join('')}</tbody></table>${properties.length?'':'<div class="empty">Nenhum imóvel cadastrado.</div>'}</div></div>`;}
function leadsAdmin(){return `<div class="flex between"><div><h1>Contato</h1><p class="muted small">Gerencie as oportunidades recebidas pelo site.</p></div><button class="btn" data-action="export" data-value="leads">${icon('download')}Exportar CSV</button></div><div class="kanban">${statuses.map(s=>`<div class="kanban-col"><div class="kanban-title"><span>${s}</span><span>${number(leads.filter(l=>l.status===s).length)}</span></div>${leads.filter(l=>l.status===s).map(l=>`<article class="lead-card"><div class="flex between"><h3 data-no-translate>${esc(l.name)}</h3><button data-action="delete-lead" data-id="${l.id}" aria-label="Excluir">${icon('trash')}</button></div><p data-no-translate>${esc(l.property)}</p><a data-no-translate href="mailto:${esc(l.email)}">${esc(l.email)}</a>${l.phone?`<a data-no-translate href="tel:${esc(l.phone.replace(/[^+\d]/g,''))}">${esc(l.phone)}</a>`:''}<p data-no-translate style="margin-top:12px">${esc(l.message)}</p><p style="margin-top:8px">${new Date(l.date).toLocaleDateString(locales[lang])}</p><p>Responsável: <strong data-no-translate>${esc(l.responsible?.name||tr('Não atribuído',lang))}</strong></p>${l.followUpAt?`<p class="${Date.parse(l.followUpAt)<Date.now()?'form-error':'note'}">Lembrete: ${new Date(l.followUpAt).toLocaleString(locales[lang])}${Date.parse(l.followUpAt)<Date.now()?' · Retorno pendente':''}</p>`:''}<div class="lead-actions"><button class="btn" data-action="lead-manage" data-id="${l.id}">Responsável e lembrete</button><button class="btn" data-action="lead-history" data-id="${l.id}">Histórico</button><button class="btn" data-action="visit-new" data-id="${l.id}">Agendar visita</button></div><select data-lead="${l.id}" aria-label="Situação">${statuses.map(t=>`<option ${s===t?'selected':''} value="${t}">${t}</option>`).join('')}</select></article>`).join('')||'<p class="muted small">Nenhum contato nesta etapa.</p>'}</div>`).join('')}</div>`;}
const field=(name,label,value='',type='text',extra='')=>`<div class="form-field ${extra.includes('full')?'full':''}"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra.replace('full','')}></div>`;
const operations=createOperationsUI({state:()=>({properties,leads,visits,staff,lang,session}),esc,field,showModal,render,refresh,api,toast});
const presentations=createPresentation({state:()=>({properties,settings,session,leads,lang}),showModal,api,toast,refresh});
const attendance=createAttendance({state:()=>({properties,leads,visits,staff,session,lang}),esc,api,render,refresh,showModal,field,toast});
const notifications=createNotifications({tr,state:()=>({session,staff,lang}),api,esc,field,toast});
function personalLanguage(){if(session.authenticated&&locales[session.language]){lang=session.language;localStorage.setItem('confianza-language',lang);}}
function settingsAdmin(){return `<h1>Configurações</h1><p class="muted small">Dados da imobiliária</p><form id="settings-form" class="panel settings-panel"><div class="form-grid">${field('name','Nome da imobiliária',settings.name,'text','required')}${field('tagline','Subtítulo da marca',settings.tagline)}${field('phone','Telefone',settings.phone)}${field('email','E-mail',settings.email,'email')}${field('whatsapp','WhatsApp (apenas dígitos)',settings.whatsapp,'text','pattern="[0-9]{8,15}"')}${field('address','Endereço',settings.address)}<label class="check-label full"><input type="checkbox" name="demo" ${settings.demo?'checked':''}>Mostrar aviso de catálogo demonstrativo</label></div><div class="form-actions"><button class="btn primary">Salvar configurações</button></div><p class="form-error" role="alert"></p></form>`;}
function teamAdmin(){return `<div class="flex between"><div><h1>Acesso da equipe</h1><p class="muted small">Gerencie os usuários e suas permissões.</p></div>${session.mode==='node'?'<button class="btn primary" data-action="edit-user">'+icon('plus')+'Novo usuário</button>':''}</div>${session.mode==='sites'?'<div class="note" style="margin-top:30px">A prévia no Sites usa sua conta ChatGPT. A gestão de usuários da equipe fica disponível na instalação Node.js da Hostinger.</div>':`<div class="panel" style="margin-top:30px"><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Idioma padrão</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${users.map(u=>`<tr><td data-no-translate>${esc(u.name)}</td><td data-no-translate>${esc(u.email)}</td><td>${{admin:'Administrador',editor:'Editor de imóveis',agent:'Corretor'}[u.role]}</td><td data-no-translate>${languageNames[u.language||'pt']}</td><td>${u.active?'Ativo':'Inativo'}</td><td><button data-action="edit-user" data-id="${u.id}" aria-label="Editar usuário">${icon('edit')}</button><button class="btn" data-action="broker-profile" data-id="${u.id}">Perfil público</button></td></tr>`).join('')}</tbody></table></div></div>`}`;}
function loginPage(){if(mfaChallenge)return `${header()}<main class="container section" style="max-width:500px;min-height:65vh"><div class="panel"><h2>Verificação em duas etapas</h2>${mfaChallenge.setupSecret?`<p>Leia o QR Code no seu aplicativo autenticador e informe o código de seis dígitos.</p>${mfaChallenge.setupQr?`<img src="${esc(mfaChallenge.setupQr)}" alt="QR Code para configurar o aplicativo autenticador" width="320" height="320" style="display:block;width:320px;max-width:100%;height:auto;margin:16px auto;image-rendering:pixelated">`:''}<p>Se não conseguir ler o QR Code, adicione esta chave manualmente. Guarde a chave em local seguro.</p><p data-no-translate style="overflow-wrap:anywhere"><code>${esc(mfaChallenge.setupSecret)}</code></p>`:'<p>Informe o código do seu aplicativo autenticador.</p>'}<form id="mfa-form"><div class="form-field"><label for="mfa-code">Código de verificação</label><input id="mfa-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required></div><p class="form-error" role="alert"></p><button class="btn primary">Verificar código</button></form><button class="btn" data-action="mfa-cancel">Voltar ao login</button></div></main>${footer()}`;return `${header()}<main class="container section" style="max-width:500px;min-height:65vh"><div class="panel"><div class="eyebrow">ÁREA ADMINISTRATIVA</div><h2>Acesso administrativo</h2><p class="muted small" style="margin:15px 0 25px">Entre com suas credenciais da equipe.</p><form id="login-form"><div class="form-grid">${field('email','E-mail','','email','full required autocomplete="username"')}${field('password','Senha','','password','full required autocomplete="current-password"')}</div><button class="btn primary" style="width:100%;margin-top:25px">Entrar</button><p class="form-error" role="alert"></p></form><a href="/admin/recuperar">${tr('Esqueci minha senha',lang)}</a></div></main>${footer()}`;}
async function render(){const r=route(),app=$('#app');document.documentElement.lang=locales[lang];document.title=(settings.name||'Confianza')+' | '+tr(r.startsWith('/admin')?'Administração':'Imóveis & Terras',lang);let html='';team.applyAccessibility();if(new URL('https://local'+r).pathname==='/admin/recuperar'){app.innerHTML=header()+team.recoveryPage()+footer();translateDOM(app,lang);return;}
 if(r.startsWith('/admin')&&session.authenticated){const pathname=new URL('https://local'+r).pathname,edit=pathname.match(/^\/admin\/imoveis\/(novo|([^/]+)\/editar)$/);if(edit){if(!canEdit()){app.innerHTML=adminShell('imoveis','<p role="alert">'+tr('Acesso restrito.',lang)+'</p>');return;}const id=edit[2]&&decodeURIComponent(edit[2]);if(id&&!properties.some(p=>p.id===id)){app.innerHTML=adminShell('imoveis','<p role="alert">'+tr('Imóvel indisponível.',lang)+'</p>');return;}mountPropertyPage(id);return;}const page=pathname.split('/')[2]||'dashboard';if((page==='equipe'||page==='configuracoes')&&session.role!=='admin'){location.href='/admin';return;}html=adminShell(page,page==='conversas'?qrUI.page():['organizar','desempenho','backups'].includes(page)?team.shell(page):page==='imoveis'?propertyAdmin():page==='contatos'?leadsAdmin():page==='visitas'?attendance.upcoming()+operations.calendar():page==='pendencias'?attendance.pending():page==='relatorios'?attendance.reports():page==='notificacoes'?notifications.page():page==='configuracoes'?settingsAdmin():page==='equipe'?teamAdmin():dashboard());}
 else if(r.startsWith('/admin'))html=loginPage();else if(r.startsWith('/imovel/'))html=detail();else if(r.startsWith('/buscar'))html=listPage();else if(r.startsWith('/favoritos'))html=listPage(true);else if(r.startsWith('/comparar'))html=comparison();else if(r.startsWith('/sobre'))html=basicPage('sobre');else if(r.startsWith('/privacidade'))html=basicPage('privacidade');else html=home();app.innerHTML=html;notifications.mount().then(()=>{if($('#notification-admin'))translateDOM($('#notification-admin'),lang);}).catch(error=>toast(error.message));team.mount().catch(error=>toast(error.message));qrUI.mount().catch(error=>toast(error.message));translateDOM(app,lang);if($('#admin-search')){const q=new URLSearchParams(location.search).get('q')??sessionStorage.getItem('property-search-'+session.id)??'';$('#admin-search').value=q;document.querySelectorAll('[data-row]').forEach(row=>row.hidden=!row.dataset.row.includes(q.toLowerCase()));}}
function showModal(label,body){$('#dialog').classList.remove('presentation-dialog');$('#dialog').innerHTML=`<div class="modal-head"><h2>${label}</h2><button data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>`;translateDOM($('#dialog'),lang);if(!$('#dialog').open)$('#dialog').showModal();}
function contactModal(id,kind='Contato'){const p=properties.find(x=>x.id===id);showModal(kind==='Visita'?'Agendar visita':kind==='Anúncio de imóvel'?'Anunciar imóvel':'Falar com a equipe',`<p>${p?esc(title(p)):tr('Conte seus planos. Nossa equipe ajuda a dar o próximo passo.',lang)}</p><form id="lead-form" data-id="${esc(id||'')}" data-kind="${esc(kind)}"><div class="form-grid">${field('name','Nome','','text','required maxlength="150" autocomplete="name"')}${field('email','E-mail','','email','required maxlength="200" autocomplete="email"')}${field('phone','Telefone','','tel','autocomplete="tel"')}${kind==='Visita'?field('visit','Data desejada','','date',`min="${new Date().toISOString().slice(0,10)}" required`):''}<div class="form-field full"><label for="message">Mensagem</label><textarea id="message" name="message" placeholder="Conte um pouco sobre o que procura." maxlength="2000"></textarea></div><input name="website" tabindex="-1" autocomplete="off" class="hidden"><label class="check-label full"><input name="consent" type="checkbox" required>Autorizo o contato da equipe para responder a esta solicitação.</label></div><p class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="button" data-action="close">Cancelar</button><button class="btn primary">Enviar solicitação ${icon('arrow')}</button></div></form>`);}
function mountPropertyPage(id){const p=properties.find(x=>x.id===id);draft=p?structuredClone(p):{id:crypto.randomUUID(),title:'',description:'',location:'',region:'Sul',type:'Casa',purpose:'Comprar',price:0,currency:'BRL',area:0,unit:'m²',beds:0,baths:0,parking:0,features:[],gallery:[],image:'',status:'Rascunho',featured:false,translations:{}};draftLang='pt';photoEditor?.dispose();showPropertyPage(id?'Editar imóvel':'Novo imóvel',`<p>Título e descrição podem ser cadastrados nos cinco idiomas. O conteúdo original é usado quando não há tradução.</p><form id="property-form"><div class="form-grid"><div class="form-field full"><label for="draft-lang">Idioma do conteúdo</label><select id="draft-lang">${Object.entries(languageNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div>${field('title','Título',draft.title,'text','full required maxlength="150"')}<div class="form-field full"><label for="draft-description">Descrição</label><textarea id="draft-description" name="description" maxlength="5000">${esc(draft.description)}</textarea></div>${selectField('type','Tipo de imóvel',['Casa','Apartamento','Fazenda','Terreno'],draft.type)}${selectField('purpose','Finalidade',['Comprar','Alugar','Lançamentos'],draft.purpose)}${field('location','Localização',draft.location,'text','required')}${selectField('region','Região',['Sul','Centro-Oeste','Sudeste','Paraguai','Nordeste','Norte'],draft.region)}<label class="check-label full"><input name="priceOnRequest" type="checkbox" ${draft.priceOnRequest?'checked':''}>Preço sob consulta</label>${field('price','Preço',draft.price,'number','min="0" step="0.01"')}${selectField('currency','Moeda',['BRL','USD'],draft.currency)}${field('area','Área',draft.area,'number','required min="0.01" step="0.01"')}${selectField('unit','Unidade',['m²','ha'],draft.unit)}${field('beds','Quartos',draft.beds,'number','min="0"')}${field('baths','Banheiros',draft.baths,'number','min="0"')}${field('parking','Vagas',draft.parking,'number','min="0"')}${selectField('status','Situação',['Publicado','Rascunho','Vendido'],draft.status)}${field('productive','Área produtiva',draft.productive||'','number','min="0" step="0.01"')}${field('reserve','Reserva natural',draft.reserve||'','number','min="0" step="0.01"')}${field('soil','Solo predominante',draft.soil||'')}${field('rain','Chuva média anual',draft.rain||'','number','min="0"')}${field('latitude','Latitude',draft.latitude||'','number','min="-90" max="90" step="any"')}${field('longitude','Longitude',draft.longitude||'','number','min="-180" max="180" step="any"')}${field('features','Características (separadas por vírgula)',draft.features.join(', '),'text','full')}<section class="form-field full" id="property-photos" data-no-translate></section>${operations.internalFields(draft)}<label class="check-label full"><input name="featured" type="checkbox" ${draft.featured?'checked':''}>Destaque na página inicial</label></div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="property-back">Cancelar</button><button class="btn primary">Salvar imóvel</button></div></form>`);photoEditor=mountPhotoEditor($('#property-photos'),draft,{lang,esc,img});}
function selectField(name,label,values,value){return `<div class="form-field"><label for="field-${name}">${label}</label><select name="${name}" id="field-${name}">${values.map(v=>`<option value="${v}" ${v===value?'selected':''}>${v}</option>`).join('')}</select></div>`;}
function saveDraftTranslation(){if(!draft)return;const t=$('#field-title').value,d=$('#draft-description').value,features=$('#field-features').value.split(',').map(x=>x.trim()).filter(Boolean);if(draftLang==='pt'){draft.title=t;draft.description=d;draft.features=features;}else{draft.translations||={};draft.translations[draftLang]={title:t,description:d,features};}}
function editUser(id){const u=users.find(x=>x.id===id)||{name:'',email:'',role:'agent',active:true};showModal(id?'Editar usuário':'Novo usuário',`<form id="user-form" data-id="${esc(id||'')}"><div class="form-grid">${field('name','Nome',u.name,'text','required')}${field('email','E-mail',u.email,'email','required')}${selectField('role','Perfil',['admin','editor','agent'],u.role)}<div class="form-field"><label for="user-language">Idioma padrão</label><select id="user-language" name="language">${Object.entries(languageNames).map(([k,v])=>`<option value="${k}" ${(u.language||'pt')===k?'selected':''}>${v}</option>`).join('')}</select></div>${field('password',id?'Nova senha (opcional)':'Senha','','password',`${id?'':'required'} minlength="12" placeholder="Mínimo de 12 caracteres" autocomplete="new-password"`)}<label class="check-label full"><input name="commissionView" type="checkbox" ${u.commissionView?'checked':''}>Visualizar comissões</label><label class="check-label full"><input name="commissionEdit" type="checkbox" ${u.commissionEdit?'checked':''}>Alterar comissões (inclui visualização)</label><p class="note full">Administradores têm acesso integral às comissões.</p><label class="check-label full"><input name="mfaRequired" type="checkbox" ${(u.mfaRequired??(u.role==='admin'))?'checked':''}>Exigir MFA</label><p class="note full">Desmarcado: entra com e-mail e senha. Alterar esta opção encerra as sessões da conta.</p><label class="check-label full"><input name="active" type="checkbox" ${u.active?'checked':''}>Ativo</label></div><p class="note">Administrador · Editor de imóveis · Corretor</p><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary">Salvar usuário</button></div></form>`);const sel=$('#field-role');sel.options[0].textContent=tr('Administrador',lang);sel.options[1].textContent=tr('Editor de imóveis',lang);sel.options[2].textContent=tr('Corretor',lang);if(!id){const mfa=$('[name=mfaRequired]');let touched=false;mfa.addEventListener('change',()=>touched=true);sel.addEventListener('change',()=>{if(!touched)mfa.checked=sel.value==='admin';});}}
async function refresh(){session=await api('session');personalLanguage();properties=await api('properties'+(session.authenticated?'?admin=1':''));if(session.authenticated){[leads,visits,staff]=await Promise.all([api('leads'),api('visits'),api('staff')]);}if(session.role==='admin'&&session.mode==='node')users=(await api('users')).users;}
function exportCSV(kind){const rows=kind==='properties'?properties:leads;const keys=kind==='properties'?['id','title','type','purpose','location','price','currency','area','status']:['id','name','email','phone','property','message','date','status'];const sanitize=x=>{let s=String(x??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\uFEFF'+[keys.map(sanitize).join(';'),...rows.map(r=>keys.map(k=>sanitize(r[k])).join(';'))].join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),'confianza-'+kind+'.csv');}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,v=el.dataset.value;try{await qrUI.action(a,id);await team.action(a,id);await operations.action(a,id,v,el);await attendance.action(a,id,v);await presentations.action(a);await notifications.action(a);
 if(a==='property-back'){leaveProperty();return;}
 if(a==='close')$('#dialog').close();if(a==='menu')$('#nav').classList.toggle('open');if(a==='navigate')location.href=v;
 if(a==='contact')contactModal(id,el.dataset.kind||'Contato');
 if(a==='favorite'){favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('confianza-favorites',JSON.stringify([...favorites]));const y=scrollY;render();scrollTo(0,y);toast(favorites.has(id)?'Adicionado aos favoritos.':'Removido dos favoritos.');}
 if(a==='purpose'){const form=$('#search-form');if(form){const f=new FormData(form);filters={...filters,q:f.get('q'),type:f.get('type'),max:f.get('max')};}purpose=v;filters.type=v==='Fazendas'?'Fazenda':'';const y=scrollY;render();scrollTo(0,y);}
 if(a==='filter'){activeFilter=v;const y=scrollY;render();scrollTo(0,y);}
 if(a==='compare')location.href='/comparar?a='+id;
 if(a==='detail-tab'){detailTab=v;const y=scrollY;render();scrollTo(0,y);}
 if(a==='gallery'){const p=properties.find(x=>x.id===decodeURIComponent(route().split('/')[2]));galleryIndex=(galleryIndex+Number(v)+Math.max(1,photoRefs(p).length))%Math.max(1,photoRefs(p).length);const y=scrollY;render();scrollTo(0,y);}
 if(a==='thumbnail'){galleryIndex=Number(v);const y=scrollY;render();scrollTo(0,y);}
 if(a==='share'){await navigator.clipboard.writeText(location.href);toast('Link copiado.');}
 if(a==='presentation')await presentations.open(id);
 if(a==='lead-presentation'){const l=leads.find(l=>l.id===id);await presentations.open(l.propertyId,id);}
 if(a==='broker-profile'){const u=users.find(u=>u.id===id),p=u.publicProfile||{enabled:false,name:'',whatsapp:'',email:''};showModal('Perfil público do corretor',`<p>Estes dados aparecem nas apresentações. Os dados de acesso da conta permanecem internos.</p><form id="broker-profile-form" data-id="${esc(id)}"><label class="check-label"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}>Permitir participação nos materiais comerciais</label>${field('publicName','Nome comercial',p.name,'text','maxlength="100"')}${field('publicWhatsapp','WhatsApp com país e DDD',p.whatsapp,'text','pattern="[1-9][0-9]{9,14}" maxlength="15"')}${field('publicEmail','E-mail profissional',p.email,'email','maxlength="200"')}<p class="form-error" role="alert"></p><div class="form-actions"><button class="btn primary">Salvar perfil público</button></div></form>`);}
 if(a==='advanced')showModal('Busca avançada',`<form id="advanced-form"><div class="form-grid">${field('q','Cidade / região',filters.q)}${selectField('type','Tipo de imóvel',['','Casa','Apartamento','Fazenda','Terreno'],filters.type)}${field('max','Faixa de preço',filters.max,'number','min="0"')}${field('minArea','Área',filters.minArea,'number','min="0" step="any"')}</div><div class="form-actions"><button class="btn primary">Buscar imóveis</button></div></form>`);
 if(a==='edit-property')editProperty(id);if(a==='edit-user')editUser(id);
 if(a==='delete-property'&&confirm(tr('Excluir este imóvel?',lang))){await api('properties/'+id,'DELETE');await refresh();render();toast('Imóvel excluído.');}
 if(a==='delete-lead'&&confirm(tr('Excluir este contato?',lang))){await api('leads/'+id,'DELETE');await refresh();render();}
 if(a==='export')exportCSV(v);
 if(a==='audit-download'){const records=await api('audit');download(new Blob([JSON.stringify(records,null,2)],{type:'application/json'}),'confianza-auditoria.json');}
 if(a==='mfa-cancel'){await api('logout','POST',{});mfaChallenge=null;render();}
 if(a==='logout'){await api('logout','POST',{});session=await api('session');properties=await api('properties');location.href='/admin';render();}
 if(a==='retry')initialize();
 }catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{const el=e.target;try{
 await team.preference(el);attendance.change(el);if(el.closest('#presentation-form'))await presentations.change?.(el);
 if(el.matches('[data-language]')){if(propertyGuard?.dirty){el.value=lang;toast('Salve ou cancele a edição antes de mudar o idioma.');return;}if(session.authenticated){await api('preferences','PUT',{language:el.value});session.language=el.value;}lang=el.value;localStorage.setItem('confianza-language',lang);render();}
 if(el.id==='sort'){sort=el.value;const y=scrollY;render();scrollTo(0,y);}
 if(el.matches('[data-compare]')){location.href='/comparar?a='+$('#compare-a').value+'&b='+$('#compare-b').value;}
 if(el.matches('#visit-property, #visit-mode'))operations.updateVisitRule();
 if(el.matches('[data-lead]')){if(el.value==='Visita agendada'){el.value=leads.find(l=>l.id===el.dataset.lead).status;operations.visitForm(el.dataset.lead);return;}await api('leads/'+el.dataset.lead,'PUT',{status:el.value,expectedRevision:leads.find(l=>l.id===el.dataset.lead).revision||0});await refresh();render();}
 if(el.id==='draft-lang'){saveDraftTranslation();draftLang=el.value;$('#field-title').value=draftLang==='pt'?draft.title:draft.translations?.[draftLang]?.title||'';$('#draft-description').value=draftLang==='pt'?draft.description:draft.translations?.[draftLang]?.description||'';$('#field-features').value=(draftLang==='pt'?draft.features:draft.translations?.[draftLang]?.features||[]).join(', ');$('#field-title').required=draftLang==='pt';}

 }catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='admin-search'){sessionStorage.setItem('property-search-'+session.id,e.target.value);const q=e.target.value.toLowerCase();document.querySelectorAll('[data-row]').forEach(row=>row.hidden=!row.dataset.row.includes(q));}});
document.addEventListener('submit',async e=>{const form=e.target;e.preventDefault();if(form.dataset.submitting==='true')return;form.dataset.submitting='true';const f=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';try{
 await qrUI.submit(form);await team.submit(form);
 if(form.id==='search-form'||form.id==='advanced-form'){filters={...filters,...f};const q=new URLSearchParams();for(const k of ['q','type','max','minArea'])if(filters[k])q.set(k,filters[k]);if(purpose==='Fazendas')q.set('type','Fazenda');else q.set('purpose',purpose);$('#dialog').close();location.href='/buscar?'+q;render();}
 if(form.id==='lead-form'){const p=properties.find(x=>x.id===form.dataset.id);await api('leads','POST',{...f,consent:!!f.consent,property:p?title(p):tr('Contato geral',lang),propertyId:p?.id||'',kind:form.dataset.kind,message:(f.visit?tr('Data desejada',lang)+': '+f.visit+'\n':'')+(f.message||'')});$('#dialog').close();toast('Solicitação enviada. Nossa equipe entrará em contato.');if(session.authenticated){[leads,visits,staff]=await Promise.all([api('leads'),api('visits'),api('staff')]);}}
 if(form.id==='login-form'){const result=await api('login','POST',f);if(result.mfaRequired){mfaChallenge=result;render();$('#mfa-code').focus();return;}session=await api('session');await refresh();location.href=location.pathname.startsWith('/admin/imoveis/')?location.pathname:'/admin';render();}
 if(form.id==='settings-form'){settings=await api('settings','PUT',{...f,demo:!!f.demo});toast('Informações salvas.');render();}
 if(form.id==='mfa-form'){await api('mfa/verify','POST',f);mfaChallenge=null;session=await api('session');await refresh();location.href=location.pathname.startsWith('/admin/imoveis/')?location.pathname:'/admin';render();}
 await notifications.submit(form);await attendance.submit(form);presentations.submit(form);
 if(form.id==='broker-profile-form'){const u=users.find(u=>u.id===form.dataset.id);await api('commercial/brokers/'+u.id,'PUT',{expectedProfile:u.publicProfile||null,profile:{enabled:!!f.enabled,name:f.publicName,whatsapp:f.publicWhatsapp,email:f.publicEmail}});$('#dialog').close();await refresh();render();}
 await operations.submitEnhancement(form);
 if(form.id==='visit-form')await operations.submitVisit(form);
 if(form.id==='property-form'){saveDraftTranslation();const p={...draft,...f,internal:operations.readInternal(form),title:draft.title,description:draft.description,translations:draft.translations,featured:!!f.featured,priceOnRequest:!!f.priceOnRequest,...photoEditor.value(),expectedUpdatedAt:draft.updatedAt||null,features:draft.features};for(const k of ['price','area','productive','reserve','rain','beds','baths','parking','latitude','longitude'])p[k]=f[k]?Number(f[k]):null;p.tag=p.type==='Fazenda'?'Fazenda premium':p.purpose==='Alugar'?'Para alugar':'Seleção Confianza';await api('properties/'+p.id,properties.some(x=>x.id===p.id)?'PUT':'POST',p);propertyGuard?.clean();photoEditor?.dispose();location.href=propertyReturn();}
 if(form.id==='user-form'){const result=await api('users'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PUT':'POST',{...f,active:!!f.active,mfaRequired:!!f.mfaRequired,commissionView:!!f.commissionView,commissionEdit:!!f.commissionEdit});$('#dialog').close();if(result.reauthenticate){session=await api('session');properties=await api('properties');location.href='/admin';render();toast('Entre com suas credenciais da equipe.');}else{await refresh();render();toast('Atualização salva.');}}
 }catch(err){if(error){error.textContent=tr(err.message,lang);error.tabIndex=-1;error.focus();}else toast(err.message);}finally{delete form.dataset.submitting;if(submit)submit.disabled=false;}});
window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#/'))return;galleryIndex=0;detailTab='Visão geral';const url=new URL('https://local'+route());if(url.pathname==='/buscar'){filters={q:url.searchParams.get('q')||'',type:url.searchParams.get('type')||'',max:url.searchParams.get('max')||'',minArea:url.searchParams.get('minArea')||'',region:url.searchParams.get('region')||''};purpose=url.searchParams.get('purpose')||(filters.type==='Fazenda'?'Fazendas':'Comprar');}$('#dialog').close();render();scrollTo(0,0);});
async function initialize(){if(location.hash.startsWith('#/')){location.replace(location.hash.slice(1));return;}try{session=await api('session');personalLanguage();[properties,settings]=await Promise.all([api('properties'+(session.authenticated?'?admin=1':'')),api('settings')]);if(session.authenticated){[leads,visits,staff]=await Promise.all([api('leads'),api('visits'),api('staff')]);}if(session.role==='admin'&&session.mode==='node')users=(await api('users')).users;const url=new URL('https://local'+route());if(url.pathname==='/buscar'){filters={...filters,...Object.fromEntries(url.searchParams)};purpose=url.searchParams.get('purpose')||(filters.type==='Fazenda'?'Fazendas':'Comprar');}render();}catch(err){$('#app').innerHTML=`<div class="container section"><h2>${tr('Não foi possível carregar os dados. Tente novamente.',lang)}</h2><button class="btn primary" style="margin-top:25px" data-action="retry">${tr('Tentar novamente',lang)}</button></div>`;}}
initialize();

$('#dialog').addEventListener('close',()=>{if(!$('#property-form')){photoEditor?.dispose();photoEditor=null;}});

document.addEventListener('click',e=>{if(!propertyGuard?.dirty)return;const target=e.target.closest('a,[data-action=navigate],[data-action=logout]');if(!target||target.getAttribute('href')?.startsWith('#'))return;if(!propertyGuard.leave()){e.preventDefault();e.stopImmediatePropagation();}},true);
